package com.masterlearning.platform.modules.assessment.controller;
import com.masterlearning.platform.common.api.ApiResponse; import com.masterlearning.platform.modules.assessment.dto.request.*; import com.masterlearning.platform.modules.assessment.entity.*; import com.masterlearning.platform.modules.assessment.repository.*; import com.masterlearning.platform.modules.course.repository.CourseRepository; import jakarta.persistence.EntityNotFoundException; import jakarta.validation.Valid; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/v1/assessments") public class AssessmentController {
 private final AssessmentRepository assessments; private final QuestionRepository questions; private final QuestionOptionRepository options; private final CourseRepository courses;
 public AssessmentController(AssessmentRepository a,QuestionRepository q,QuestionOptionRepository o,CourseRepository c){assessments=a;questions=q;options=o;courses=c;}
 @PostMapping("/courses/{courseId}") @PreAuthorize("hasAnyRole('SUPER_ADMIN','ADMIN','INSTRUCTOR')") public ApiResponse<Map<String,Object>> create(@PathVariable UUID courseId,@Valid @RequestBody CreateAssessmentRequest r){var c=courses.findById(courseId).orElseThrow(()->new EntityNotFoundException("Course not found"));var a=assessments.save(new Assessment(c,r.title(),r.passingScore()));return ApiResponse.success("Assessment created",Map.of("id",a.getId(),"title",a.getTitle()));}
 @PostMapping("/{assessmentId}/questions") @PreAuthorize("hasAnyRole('SUPER_ADMIN','ADMIN','INSTRUCTOR')") public ApiResponse<Map<String,Object>> question(@PathVariable UUID assessmentId,@Valid @RequestBody CreateQuestionRequest r){var a=assessments.findById(assessmentId).orElseThrow(()->new EntityNotFoundException("Assessment not found"));if(r.options().stream().noneMatch(CreateQuestionRequest.Option::correct))throw new IllegalArgumentException("At least one correct option is required");var q=questions.save(new Question(a,r.questionText(),r.questionType()==null?"SINGLE_CHOICE":r.questionType(),r.points()));r.options().forEach(x->options.save(new QuestionOption(q,x.text(),x.correct())));return ApiResponse.success("Question created",Map.of("id",q.getId()));}
}